-- ----------------------------
-- Table structure for product
-- ----------------------------
DROP TABLE IF EXISTS `product`;
CREATE TABLE `product`  (
  `id` int(50) NOT NULL AUTO_INCREMENT COMMENT '商品id',
  `product_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '商品名称',
  `type_id` int(50) NULL DEFAULT NULL COMMENT '商品所属分类ID',
  `price` decimal(10, 2) NULL DEFAULT NULL COMMENT '商品价格',
  `description` varchar(255) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '商品描述',
  `update_time` timestamp(6) NULL DEFAULT NULL COMMENT '商品修改时间',
  `create_time` timestamp(6) NULL DEFAULT NULL COMMENT '商品创建时间',
  `img_url` varchar(255) CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT NULL COMMENT '商品图片url',
  `is_deleted` bit(1) NULL DEFAULT NULL COMMENT '是否删除',
  `status` enum('DRAFT','PUBLISHED','UNPUBLISHED') CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT 'DRAFT' COMMENT '商品状态',
  `publish_start` timestamp(6) NULL DEFAULT NULL COMMENT '商品上架开始时间',
  `publish_end` timestamp(6) NULL DEFAULT NULL COMMENT '商品上架结束时间',
  `seller_id` int(50) NULL DEFAULT NULL COMMENT '卖家ID',
  `ways` enum('included','excluded','selfpick') CHARACTER SET utf8 COLLATE utf8_bin NULL DEFAULT 'included' COMMENT '发货方式',
  `postage` decimal(10, 2) NULL DEFAULT NULL COMMENT '邮费',
  `donation_percent` double(255, 2) NULL DEFAULT NULL COMMENT '捐赠比例',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6023 CHARACTER SET = utf8 COLLATE = utf8_bin ROW_FORMAT = Dynamic;

